"""A design system's generated files, as Claude's Design System type writes them "on every save and
build": tokens.css (compiled from tokens.json), manifest.json (v3, the component catalogue), the api/
cards agents read (tokens.md, components/<Comp>.md with props from index.d.ts, assets/<Group>.md) and
README.md's generated tail ("Consuming this system" and "Index"). The grammar is the same as the
page's compiler (types/_kit/ds.js): a value that page would drop drops here too.

Run on every publish and every save of a design-system artifact, so a system Hermes wrote, one the
user edited and one brought over from Claude all read the same to the next agent.
"""

from __future__ import annotations

import json
import re
from typing import Any, Optional

NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$")
HEX = re.compile(r"^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$", re.I)
FN = re.compile(r"^(rgba?|hsla?|oklch|oklab|lab|lch|color)\(([^()]*)\)$", re.I)
LEN = re.compile(r"^-?(\d+(\.\d+)?|\.\d+)(px|rem|em|%)$")
CORE = {"color", "type", "spacing", "radius", "shadow"}
SKIP = {"name", "version", "meta", "$schema", "description", "motion"}
CAPS = {"themes": 8, "colors": 600, "fonts": 4096, "families": 12, "groups": 12, "styles": 80, "perFamily": 60, "otherFamilies": 12}
GEN_MARK = "<!-- @generated by the Design System type on every save and build — do not edit -->"
README_MARK = "<!-- @generated below by the Design System type: Consuming this system, Index -->"


def _s(v: Any) -> str:
    if isinstance(v, str):
        return v.strip()
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return str(v)
    return ""


def _clamp(v: Any, n: int) -> str:
    s = _s(v)
    return s[:n]


def _clean(v: Any) -> str:
    return re.sub(r"^(--|\.)", "", _s(v))


def _css_name(n: str) -> str:
    return n.replace(".", "\\.")


def _is_list(f: Any) -> bool:
    return isinstance(f, dict) and isinstance(f.get("tokens"), list)


def _color_value(v: Any) -> dict:
    v = _s(v)
    if HEX.match(v):
        return {"ok": v.lower()}
    m = FN.match(v)
    if m:
        args = re.sub(r"(srgb-linear|srgb|display-p3|a98-rgb|prophoto-rgb|rec2020|xyz-d50|xyz-d65|xyz|none)", " ", m.group(2), flags=re.I)
        args = re.sub(r"(\d)(deg|grad|rad|turn)", r"\1", args, flags=re.I)
        if re.fullmatch(r"[\d\s.,%/+-]*", args) and re.search(r"\d", args):
            return {"ok": v}
        return {"bad": "a colour function takes plain numbers only (no var(), url(), color-mix(), names)"}
    a = re.fullmatch(r"\{([^{}]+)\}", v)
    if a:
        return {"alias": _clean(a.group(1))}
    if re.match(r"^var\(", v, re.I):
        return {"bad": 'var() is not a colour value; alias another token as "{name}"'}
    if re.match(r"^color-mix\(", v, re.I):
        return {"bad": "color-mix() is not read; write the mixed colour"}
    if re.fullmatch(r"[a-z]+", v, re.I):
        return {"bad": f'named colours ("{v}") drop; write hex or rgb()'}
    return {"bad": ("not a colour the page reads: " + v[:40]) if v else "no value"}


def _length(v: Any, unitless: bool = False) -> Optional[str]:
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return str(v) if unitless and v < 10 else f"{v:g}px"
    v = _s(v)
    if v == "0":
        return "0"
    if LEN.match(v):
        return v
    if unitless and re.fullmatch(r"\d+(\.\d+)?", v) and float(v) < 10:
        return v
    if re.fullmatch(r"\d+(\.\d+)?", v):
        return v + "px"
    return None


def _weight(v: Any) -> Optional[str]:
    if v == "normal":
        return "400"
    if v == "bold":
        return "700"
    s = _s(v)
    if re.fullmatch(r"\d{1,4}", s) and 1 <= int(s) <= 1000:
        return s
    r = re.fullmatch(r"(\d{1,4})\s+(\d{1,4})", s)
    if r and 1 <= int(r.group(1)) <= int(r.group(2)) <= 1000:
        return f"{r.group(1)} {r.group(2)}"
    return None


def _stack(v: Any) -> Optional[str]:
    v = _s(v)
    if not v or len(v) > 200 or re.search(r"[;{}<>\\()]", v):
        return None
    if v.count('"') % 2 or v.count("'") % 2:
        return None
    return v


def _shadow_value(v: Any) -> dict:
    v = _s(v)
    if not v or len(v) > 400:
        return {"bad": "a shadow is at most 400 characters" if v else "no value"}
    if re.search(r"var\(|url\(", v, re.I):
        return {"bad": "no var() or url() in a shadow"}
    if not re.fullmatch(r"[A-Za-z0-9 #%(),./+-]+", v):
        return {"bad": "not a box-shadow the page reads"}
    rest = re.sub(r"#[0-9a-f]+", "", v, flags=re.I)
    rest = re.sub(r"\b(rgba?|hsla?|oklch|oklab|lab|lch|color)\([^()]*\)", "", rest, flags=re.I)
    rest = re.sub(r"-?(\d+(\.\d+)?|\.\d+)(px|rem|em|%)?", "", rest)
    for w in re.findall(r"[a-z][a-z-]*", rest, re.I):
        if w.lower() not in ("inset", "none"):
            return {"bad": "named colours and keywords other than inset and none drop"}
    return {"ok": v}


def _plain(v: Any) -> Optional[str]:
    v = _s(v)
    if not v or len(v) > 200 or not re.fullmatch(r"[A-Za-z0-9 #%(),./+_-]+", v) or re.search(r"url\(|var\(", v, re.I):
        return None
    d = 0
    for ch in v:
        if ch == "(":
            d += 1
        elif ch == ")":
            d -= 1
            if d < 0:
                return None
    return v if d == 0 else None


def _title(key: str) -> str:
    s = re.sub(r"([a-z])([A-Z])", r"\1 \2", key)
    s = re.sub(r"[-_]+", " ", s).lower()
    return s[:1].upper() + s[1:]


def model(tokens: Any) -> dict:
    """The tokens as the page reads them, with every drop as a problem."""
    tokens = tokens if isinstance(tokens, dict) else {}
    problems: list = []
    used: dict = {}

    def drop(family, name, reason):
        problems.append({"family": family, "name": name or "", "reason": reason})

    def claim(family, name):
        if name in used:
            drop(family, name, f"the name is used already ({used[name]}): a duplicate drops")
            return False
        used[name] = family
        return True

    col = tokens.get("color")
    themes: list = []
    if isinstance(col, dict) and not _is_list(col) and not isinstance(col.get("themes"), list):
        drop("color", "", 'a name-to-value map: the page reads {"tokens": [{name, value, usage}]}')
    for t in (col.get("themes") if isinstance(col, dict) and isinstance(col.get("themes"), list) else []):
        t = t if isinstance(t, dict) else {}
        tid = _s(t.get("id") or t.get("name")).lower()
        nm = _s(t.get("name") or t.get("id"))
        if not NAME.match(tid):
            drop("color", tid, "a theme id is letters, digits, _ . -")
            continue
        if any(x["id"] == tid for x in themes):
            drop("color", tid, "a theme listed twice")
            continue
        if len(themes) >= CAPS["themes"]:
            drop("color", tid, "at most 8 themes")
            continue
        themes.append({"id": tid, "name": nm or tid})
    if not themes:
        themes.append({"id": "default", "name": "Default", "implicit": True})
    first = themes[0]["id"]
    theme_ids = [t["id"] for t in themes]
    colors: list = []
    for t in (col["tokens"] if _is_list(col) else []):
        t = t if isinstance(t, dict) else {}
        name = _clean(t.get("name"))
        if not NAME.match(name):
            drop("color", name, "a name is letters, digits, _ . - (no spaces, no /), up to 64")
            continue
        if len(colors) >= CAPS["colors"]:
            drop("color", name, "at most 600 colours")
            continue
        raw = t.get("value")
        per: dict = {}
        multi = isinstance(raw, dict)
        if multi:
            for k, v in raw.items():
                if k.lower() not in theme_ids:
                    drop("color", name, f'no theme "{k}": that value drops')
                elif v is not None:
                    per.setdefault(k.lower(), v)
        else:
            per[first] = raw
        vals, bad = {}, []
        for th, v in per.items():
            r = _color_value(v)
            if "bad" in r:
                bad.append((th + ": " if multi else "") + r["bad"])
            else:
                vals[th] = r
        if not vals:
            drop("color", name, ("; ".join(bad) or "no value") + " (the token drops)")
            continue
        for b in bad:
            drop("color", name, b + " (that theme inherits the first)")
        if not claim("color", name):
            continue
        colors.append({"name": name, "values": vals, "usage": _clamp(t.get("usage"), 1000), "raw": t})
    by = {c["name"]: c for c in colors}

    def follow(name, th, depth, seen):
        c = by.get(name)
        if not c:
            return None
        v = c["values"].get(th) or c["values"].get(first) or next(iter(c["values"].values()), None)
        if not v:
            return None
        if "ok" in v:
            return v["ok"]
        if depth > 16 or v["alias"] in seen:
            return None
        seen.add(v["alias"])
        return follow(v["alias"], th, depth + 1, seen)

    def check_aliases(c):
        keep, bad = False, []
        multi = isinstance(c["raw"].get("value"), dict)
        for th in list(c["values"]):
            v = c["values"][th]
            if "alias" not in v:
                keep = True
                continue
            why = "an alias of itself" if v["alias"] == c["name"] else (
                "an alias of a missing token {" + v["alias"] + "}" if v["alias"] not in by else None)
            if not why and follow(v["alias"], th, 1, {c["name"]}) is None:
                why = "an alias cycle or a chain over 16 deep"
            if why:
                bad.append((th + ": " if multi else "") + why)
                del c["values"][th]
            else:
                keep = True
        if not keep:
            used.pop(c["name"], None)
            by.pop(c["name"], None)
            drop("color", c["name"], "; ".join(bad) + " (the token drops)")
        else:
            for b in bad:
                drop("color", c["name"], b + " (that theme inherits the first)")
        return keep

    while True:
        before = len(colors)
        colors = [c for c in colors if check_aliases(c)]
        if len(colors) == before:
            break
    for c in colors:
        if first not in c["values"]:
            c["values"][first] = next(iter(c["values"].values()))

    ty = tokens.get("type") if isinstance(tokens.get("type"), dict) else {}
    families, fkeys = {}, []
    for k, v in (ty.get("families") if isinstance(ty.get("families"), dict) else {}).items():
        key = _s(k).lower()
        if not NAME.match(key):
            drop("type", k, "a family key is letters, digits, _ . -")
            continue
        if len(fkeys) >= CAPS["families"]:
            drop("type", k, "at most 12 families")
            continue
        s = _stack(v)
        if not s:
            drop("type", k, "a font-family stack: ≤200 characters, no ; { } < > \\ ( ), balanced quotes")
            continue
        families[key] = s
        fkeys.append(key)
    fonts = []
    for f in (ty.get("fonts") if isinstance(ty.get("fonts"), list) else []):
        f = f if isinstance(f, dict) else {}
        fam, file = _s(f.get("family")), _s(f.get("file"))
        if not fam or re.search(r"[\"';{}<>\\()]", fam):
            drop("type", fam, "a font's family is a bare name (no quotes)")
            continue
        if not file:
            drop("type", fam, "a font needs its file")
            continue
        if "/" not in file:
            file = "fonts/" + file
        if re.search(r"(^|/)\.\.(/|$)|^/|\\", file):
            drop("type", fam, "a font file is a relative path")
            continue
        w = "400" if f.get("weight") is None else _weight(f.get("weight"))
        if not w:
            drop("type", fam, 'weight: "400" or "300 800"')
            continue
        st = _s(f.get("style") or "normal")
        if st not in ("normal", "italic", "oblique"):
            drop("type", fam, "style: normal, italic or oblique")
            continue
        fonts.append({"family": fam, "file": file, "weight": w, "style": st})
    groups, style_names, nstyles = [], set(), 0
    for g in (ty.get("groups") if isinstance(ty.get("groups"), list) else []):
        g = g if isinstance(g, dict) else {}
        if len(groups) >= CAPS["groups"]:
            drop("type", _s(g.get("name")), "at most 12 type groups")
            continue
        gfam = _s(g.get("family")).lower()
        out = {"name": _s(g.get("name")) or "Text", "family": gfam, "styles": []}
        for s in (g.get("styles") if isinstance(g.get("styles"), list) else []):
            s = s if isinstance(s, dict) else {}
            name = _clean(s.get("name"))
            if not NAME.match(name):
                drop("type", name, "a style name is letters, digits, _ . -")
                continue
            if name in style_names:
                drop("type", name, "a style name used twice: the duplicate drops")
                continue
            if nstyles >= CAPS["styles"]:
                drop("type", name, "at most 80 styles")
                continue
            size = _length(s.get("fontSize"))
            if not size:
                drop("type", name, "fontSize is a length (px, rem, em, %): the style drops")
                continue
            st = {"name": name, "fontSize": size, "usage": _clamp(s.get("usage"), 1000), "sample": _clamp(s.get("sample"), 200)}
            fam = _s(s.get("family")).lower() or gfam
            if fam and fam in families:
                st["family"] = fam
            elif fam:
                drop("type", name, f'no family "{fam}" in type.families')
            if s.get("lineHeight") is not None:
                lh = _length(s.get("lineHeight"), True)
                if lh:
                    st["lineHeight"] = lh
                else:
                    drop("type", name, "lineHeight: a length or a unitless number below 10")
            if s.get("fontWeight") is not None:
                fw = _weight(s.get("fontWeight"))
                if fw:
                    st["fontWeight"] = fw.split(" ")[0]
                else:
                    drop("type", name, "fontWeight: 1–1000")
            if s.get("letterSpacing") is not None:
                ls = _length(s.get("letterSpacing"))
                if ls:
                    st["letterSpacing"] = ls
                else:
                    drop("type", name, "letterSpacing: a length")
            if s.get("fontStyle") is not None:
                if _s(s.get("fontStyle")) in ("normal", "italic"):
                    st["fontStyle"] = _s(s.get("fontStyle"))
                else:
                    drop("type", name, "fontStyle: normal or italic")
            if s.get("opticalSize") is not None:
                try:
                    st["opticalSize"] = float(s.get("opticalSize"))
                except (TypeError, ValueError):
                    drop("type", name, "opticalSize: a number")
            style_names.add(name)
            nstyles += 1
            out["styles"].append(st)
        groups.append(out)

    fams = []

    def family(key, kind):
        f = tokens.get(key)
        out = {"key": key, "title": _title(key), "kind": kind, "note": _clamp(f.get("note") if isinstance(f, dict) else "", 400), "tokens": []}
        if not _is_list(f):
            if isinstance(f, dict):
                drop(key, "", 'a name-to-value map: the page reads {"tokens": [{name, value, usage}]}')
            return None
        for t in f["tokens"]:
            t = t if isinstance(t, dict) else {}
            name = _clean(t.get("name"))
            if not NAME.match(name):
                drop(key, name, "a name is letters, digits, _ . - (no spaces, no /), up to 64")
                continue
            if len(out["tokens"]) >= CAPS["perFamily"]:
                drop(key, name, "at most 60 tokens a family")
                continue
            tok = {"name": name, "usage": _clamp(t.get("usage"), 1000)}
            if kind == "length":
                v = _length(t.get("value"))
                if not v:
                    drop(key, name, "a length (px, rem, em, %) or a number")
                    continue
                tok["value"] = v
            elif kind == "shadow":
                raw = t.get("value")
                multi = isinstance(raw, dict)
                per = {k.lower(): v for k, v in raw.items() if k.lower() in theme_ids} if multi else {first: raw}
                vals, bad = {}, []
                for th, v in per.items():
                    r = _shadow_value(v)
                    if "bad" in r:
                        bad.append((th + ": " if multi else "") + r["bad"])
                    else:
                        vals[th] = r["ok"]
                if not vals:
                    drop(key, name, ("; ".join(bad) or "no value") + " (the token drops)")
                    continue
                for b in bad:
                    drop(key, name, b + " (that theme inherits the first)")
                vals.setdefault(first, next(iter(vals.values())))
                tok["values"], tok["value"] = vals, vals[first]
            else:
                p = _plain(t.get("value"))
                if p is None:
                    drop(key, name, "a plain CSS value: letters, digits, # % ( ) , . / + _ -, no url() or var()")
                    continue
                tok["value"] = p
            if not claim(key, name):
                continue
            out["tokens"].append(tok)
        return out

    for key, kind in (("spacing", "length"), ("radius", "length"), ("shadow", "shadow")):
        if tokens.get(key) is not None:
            f = family(key, kind)
            if f:
                fams.append(f)
    others = 0
    for k in tokens:
        if k in CORE or k in SKIP:
            continue
        if not _is_list(tokens[k]):
            if isinstance(tokens[k], dict):
                drop(k, "", 'kept, not shown: a family is {"tokens": [{name, value, usage}]}')
            continue
        others += 1
        if others > CAPS["otherFamilies"]:
            drop(k, "", "at most 12 further families")
            continue
        f = family(k, "plain")
        if f:
            fams.append(f)

    def color(c, th):
        v = c["values"].get(th) or c["values"][first]
        return v["ok"] if "ok" in v else "var(--" + _css_name(v["alias"]) + ")"

    def resolve(name, th=None):
        return follow(name, th or first, 0, set())

    return {"themes": themes, "first": first, "colors": colors, "families": fams, "problems": problems,
            "type": {"families": families, "familyKeys": fkeys, "fonts": fonts, "groups": groups},
            "color": color, "resolve": resolve}


def _decl(name: str, v: str) -> str:
    return f"  --{_css_name(name)}: {v};\n"


def _css_class(n: str) -> str:
    n = n.replace(".", "\\.")
    return ("\\3" + n[0] + " " + n[1:]) if n[:1].isdigit() else n


def compile_css(tokens: Any, title: str = "") -> tuple[str, dict]:
    """tokens.css exactly as the page compiles it (its first line says it is generated)."""
    m = model(tokens)
    first = m["first"]
    out = f"/* {title or 'Design system'} — generated from tokens.json */\n"
    aliases = {id(c) for c in m["colors"] if any("alias" in v for v in c["values"].values())}
    shadows = [t for f in m["families"] if f["kind"] == "shadow" for t in f["tokens"]]
    out += f':root, [data-theme="{first}"] {{\n'
    for c in m["colors"]:
        out += _decl(c["name"], m["color"](c, first))
    for s in shadows:
        out += _decl(s["name"], s["values"][first])
    out += "}\n"
    for th in m["themes"][1:]:
        body = ""
        for c in m["colors"]:
            v = c["values"].get(th["id"])
            if (v and v != c["values"][first]) or id(c) in aliases:
                body += _decl(c["name"], m["color"](c, th["id"]))
        for s in shadows:
            if s["values"].get(th["id"]) and s["values"][th["id"]] != s["values"][first]:
                body += _decl(s["name"], s["values"][th["id"]])
        out += f'[data-theme="{th["id"]}"] {{\n{body}}}\n'
    root = "".join(_decl(t["name"], t["value"]) for f in m["families"] if f["kind"] != "shadow" for t in f["tokens"])
    root += "".join(_decl("font-" + k, m["type"]["families"][k]) for k in m["type"]["familyKeys"])
    if root:
        out += ":root {\n" + root + "}\n"
    for g in m["type"]["groups"]:
        for s in g["styles"]:
            out += "." + _css_class(s["name"]) + " {\n"
            if s.get("family"):
                out += f"  font-family: var(--font-{_css_name(s['family'])});\n"
            out += f"  font-size: {s['fontSize']};\n"
            for k, prop in (("lineHeight", "line-height"), ("fontWeight", "font-weight"), ("letterSpacing", "letter-spacing"), ("fontStyle", "font-style")):
                if s.get(k):
                    out += f"  {prop}: {s[k]};\n"
            if s.get("opticalSize") is not None:
                out += f"  font-variation-settings: 'opsz' {s['opticalSize']:g};\n"
            out += "}\n"
    for f in m["type"]["fonts"]:
        file = f["file"]
        fmt = "woff2" if file.lower().endswith(".woff2") else "woff" if file.lower().endswith(".woff") else \
            "opentype" if file.lower().endswith(".otf") else "collection" if file.lower().endswith(".ttc") else "truetype"
        out += ('@font-face {\n  font-family: "' + f["family"] + '";\n  src: url("' + file.replace('"', "%22") + '") format("' + fmt + '");\n'
                f"  font-weight: {f['weight']};\n  font-style: {f['style']};\n  font-display: swap;\n}}\n")
    return out, m


# ---------------------------------------------------------------- components and their props

_MARKER = re.compile(r"^\s*<!--\s*@dsCard\b(.*?)-->")


def _marker(src: str) -> dict:
    m = _MARKER.match(src or "")
    if not m:
        return {}
    out = {}
    for mm in re.finditer(r'(\w+)\s*=\s*(?:"([^"]*)"|([^\s"]+))', m.group(1)):
        out[mm.group(1)] = mm.group(2) if mm.group(2) is not None else mm.group(3)
    for flag in ("floor", "page"):
        if re.search(r"\b" + flag + r"\b(?!\s*=)", m.group(1)):
            out.setdefault(flag, True)
    return out


def _summary(md: str) -> str:
    text = re.sub(r"^#\s+.*\n", "", md or "", count=1).strip()
    text = re.sub(r"```.*?```", "", text, flags=re.S)
    para = text.split("\n\n")[0].replace("\n", " ").strip()
    m = re.match(r"(.+?[.!?])(\s|$)", para)
    return (m.group(1) if m else para)[:300]


def _bundle_header(js: str) -> dict:
    m = re.match(r"\s*/\*\s*@ds-bundle:\s*(\{.*?\})\s*\*/", js or "", re.S)
    if not m:
        return {}
    try:
        h = json.loads(m.group(1))
        return h if isinstance(h, dict) else {}
    except ValueError:
        return {}


def props_of(dts: str, comp: str) -> list[dict]:
    """The props a component's `<Comp>Props` declares in index.d.ts: [{name, type, optional, note}]."""
    if not dts:
        return []
    m = re.search(r"(?:export\s+)?(?:declare\s+)?(?:interface|type)\s+" + re.escape(comp) + r"Props\b[^{]*\{", dts)
    if not m:
        return []
    i, depth = m.end(), 1
    while i < len(dts) and depth:
        depth += {"{": 1, "}": -1}.get(dts[i], 0)
        i += 1
    body = dts[m.end():i - 1]
    # Members split on ; or a newline at the top level (not inside braces, parens, brackets or <>).
    parts, cur, depth = [], "", 0
    for ch in body:
        if ch in "{([<":
            depth += 1
        elif ch in "})]>" and depth:
            depth -= 1
        if depth == 0 and ch in (";", chr(10)):
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    out, note = [], ""
    for part in parts:
        s2 = part.strip()
        while True:  # a leading doc comment is the next member's note
            c = re.match(r"^/\*\*?\s*(.*?)\s*\*/\s*", s2, re.S) or re.match(r"^//\s*([^\n]*)\n?\s*", s2)
            if not c:
                break
            note = re.sub(r"\s*\n\s*\*?\s*", " ", c.group(1)).strip()
            s2 = s2[c.end():].strip()
        p = re.match(r"^(?:readonly\s+)?([A-Za-z_$][\w$]*)(\?)?\s*:\s*(.+)$", s2, re.S)
        if p:
            out.append({"name": p.group(1), "type": re.sub(r"\s+", " ", p.group(3)).strip().rstrip(","), "optional": bool(p.group(2)), "note": note})
            note = ""
    return out


def components(files: dict) -> list[dict]:
    """The catalogue in display order: the bundle header's names, then each components/<Comp>/ folder."""
    header = _bundle_header(files.get("components/bundle.js", "") if isinstance(files.get("components/bundle.js"), str) else "")
    names = [c.get("name") for c in header.get("components", []) if isinstance(c, dict) and isinstance(c.get("name"), str)]
    for p in sorted(files):
        m = re.match(r"^components/([A-Za-z_$][\w$]*)/(preview\.html|README\.md)$", p)
        if m and m.group(1) != "Cover" and m.group(1) not in names:
            names.append(m.group(1))
    out = []
    for n in names:
        prev = files.get(f"components/{n}/preview.html")
        mk = _marker(prev) if isinstance(prev, str) else {}
        readme = files.get(f"components/{n}/README.md")
        c = {"name": n}
        if mk.get("group"):
            c["group"] = mk["group"]
        if isinstance(readme, str) and readme.strip():
            c["summary"] = _summary(readme)
        if mk.get("page"):
            c["page"] = True
        out.append(c)
    return out


# ---------------------------------------------------------------- the generated files

def _cell(s: Any) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def tokens_card(m: dict, title: str) -> str:
    th = m["themes"]
    out = [GEN_MARK, f"# Tokens — {title}", "",
           "Every token, as `var(--name)` in CSS (`tokens.css`), per theme. The first theme is the default; "
           "set `data-theme` on the root for another.", ""]
    if m["colors"]:
        out += ["## Colors", "", "| token | " + " | ".join(t["name"] for t in th) + " | usage |", "| --- |" + " --- |" * len(th) + " --- |"]
        for c in m["colors"]:
            vals = []
            for t in th:
                v = c["values"].get(t["id"])
                vals.append(("`" + (v.get("ok") or "{" + v["alias"] + "}") + "`") if v else "inherits")
            out.append(f"| `--{c['name']}` | " + " | ".join(vals) + f" | {_cell(c['usage'])} |")
        out.append("")
    ty = m["type"]
    if ty["familyKeys"]:
        out += ["## Font families", "", "| token | stack |", "| --- | --- |"]
        out += [f"| `--font-{k}` | `{_cell(ty['families'][k])}` |" for k in ty["familyKeys"]]
        out.append("")
    if ty["groups"]:
        out += ["## Type styles", "", "Each style is a class (`.name`) in tokens.css.", "", "| class | family | size | line | weight | usage |",
                "| --- | --- | --- | --- | --- | --- |"]
        for g in ty["groups"]:
            for s in g["styles"]:
                out.append(f"| `.{s['name']}` | {s.get('family', '')} | {s['fontSize']} | {s.get('lineHeight', '')} | {s.get('fontWeight', '')} | {_cell(s['usage'])} |")
        out.append("")
    for f in m["families"]:
        out += [f"## {f['title']}", ""]
        if f["kind"] == "shadow":
            out += ["| token | " + " | ".join(t["name"] for t in th) + " | usage |", "| --- |" + " --- |" * len(th) + " --- |"]
            out += [f"| `--{t['name']}` | " + " | ".join("`" + t["values"].get(x["id"], t["value"]) + "`" for x in th) + f" | {_cell(t['usage'])} |" for t in f["tokens"]]
        else:
            out += ["| token | value | usage |", "| --- | --- | --- |"]
            out += [f"| `--{t['name']}` | `{t['value']}` | {_cell(t['usage'])} |" for t in f["tokens"]]
        out.append("")
    if m["problems"]:
        out += ["## Dropped", "", "Values the page can't read (fix them in tokens.json):", ""]
        out += [f"- {p['family']} `{p['name']}`: {p['reason']}" for p in m["problems"][:60]]
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def component_card(c: dict, ns: str, dts: str) -> str:
    n = c["name"]
    full = f"{ns}.{n}" if ns else n
    out = [GEN_MARK, f"# {n}", ""]
    if c.get("summary"):
        out += [c["summary"], ""]
    out += [f"`{full}`" + (f" · {c['group']}" if c.get("group") else ""), "", "## Use", "", "```jsx", f"<{full} />", "```", "",
            "```html", f'<x-import component-from-global-scope="{full}"></x-import>', "```", ""]
    props = props_of(dts, n)
    out += [f"## Props ({n}Props)", ""]
    if props:
        out += ["| prop | type | note |", "| --- | --- | --- |"]
        out += [f"| `{p['name']}`{'' if p['optional'] else ' (required)'} | `{_cell(p['type'])}` | {_cell(p['note'])} |" for p in props]
        ext = re.search(r"(?:interface|type)\s+" + re.escape(n) + r"Props\s+(?:extends\s+([^{]+)|=\s*([^{&]+)&)", dts or "")
        if ext:
            out += ["", f"_Also accepts: {(ext.group(1) or ext.group(2)).strip()}._"]
    else:
        out.append("This component declares no props.")
    out += ["", "## More", "", f"Long-form usage: `components/{n}/README.md`.", ""]
    return "\n".join(out)


def asset_card(group: str, paths: list[str], files: dict) -> str:
    out = [GEN_MARK, f"# Assets — {group}", ""]
    note = files.get(f"assets/{group}/README.md")
    if isinstance(note, str) and note.strip():
        out += [note.strip(), ""]
    out += ["| file | type | size |", "| --- | --- | --- |"]
    for p in paths:
        v = files[p]
        size = len(v) if isinstance(v, (bytes, bytearray)) else len(str(v).encode("utf-8"))
        out.append(f"| `{p}` | {p.rsplit('.', 1)[-1].lower() if '.' in p else ''} | {size} B |")
    out.append("")
    out.append("Read a file by its path (`artifact_read` with `path`). An image shows only through `<img>`; a single-ink "
               "mark's ink is named in this group's README.")
    return "\n".join(out) + "\n"


def readme_tail(index: dict, m: dict, comps: list, groups: list[str]) -> str:
    ns = index.get("namespace") or ""
    libs = index.get("libraries") if isinstance(index.get("libraries"), list) else []
    lines = ["", "---", README_MARK, "", "## Consuming this system", ""]
    lines.append("- **Tokens:** load `tokens.css` (every token as `var(--name)`, a class per type style, `@font-face` per font); "
                 "set `data-theme=\"<id>\"` on the root for a theme other than the first (`" + m["first"] + "`).")
    if ns:
        lines.append("- **Components:** load `components/bundle.css`, then " +
                     (", ".join(f"{lib.get('name')} {lib.get('version', '')}".strip() for lib in libs if isinstance(lib, dict)) + ", then " if libs else "") +
                     f"`components/bundle.js`: they are `window.{ns}.<Name>`. Read a component's card before using it.")
    fams = m["type"]["families"]
    if fams:
        lines.append("- **Fonts:**")
        for k in m["type"]["familyKeys"]:
            files_ = [f["file"] for f in m["type"]["fonts"] if f["family"].lower() in fams[k].lower()]
            lines.append(f"  - `--font-{k}`: {fams[k]} — " + (", ".join(f"`{x}`" for x in files_) if files_ else "no file here: hosted or system faces"))
    lines.append("- Use the tokens and components as this README says; never paste their values into a page raw.")
    lines += ["", "## Index", "", "- `api/tokens.md` — every token per theme"]
    lines += [f"- `api/components/{c['name']}.md` — {c.get('summary') or c['name']}" for c in comps]
    lines += [f"- `api/assets/{g}.md` — the {g} files" for g in groups]
    return "\n".join(lines) + "\n"


def build(files: dict, index: Optional[dict] = None) -> dict:
    """The generated files for a system's file table ({path: text | bytes}). Returns {path: text} to
    write; tokens.css only where the system has none of its own (or ours)."""
    index = index if isinstance(index, dict) else {}
    title = str(index.get("title") or "Design system")
    try:
        tokens = json.loads(files["tokens.json"]) if isinstance(files.get("tokens.json"), str) else {}
    except ValueError:
        tokens = {}
    css, m = compile_css(tokens, title)
    out: dict = {}
    old_css = files.get("tokens.css")
    if not isinstance(old_css, str) or re.match(r"\s*/\*[^*]*generated from tokens\.json\s*\*/", old_css):
        out["tokens.css"] = css
    comps = components(files)
    dts = files.get("components/index.d.ts") if isinstance(files.get("components/index.d.ts"), str) else ""
    ns = str(index.get("namespace") or _bundle_header(files.get("components/bundle.js", "") if isinstance(files.get("components/bundle.js"), str) else "").get("namespace") or "")
    out["api/tokens.md"] = tokens_card(m, title)
    for c in comps:
        out[f"api/components/{c['name']}.md"] = component_card(c, ns, dts)
    by_group: dict = {}
    for p in sorted(files):
        if p.startswith("assets/") and not p.endswith("/README.md"):
            parts = p.split("/")
            g = parts[1] if len(parts) > 2 else "Other"
            by_group.setdefault(g, []).append(p)
    for g, paths in by_group.items():
        out[f"api/assets/{g}.md"] = asset_card(g, paths, files)
    groups_order = [g for g in (index.get("groups") or []) if g in by_group] + [g for g in by_group if g not in (index.get("groups") or [])]
    ag = index.get("assetGroups") if isinstance(index.get("assetGroups"), dict) else {}
    manifest = {"manifestVersion": 3, "name": title, "namespace": ns,
                "files": sorted(p for p in files if not p.startswith("api/") and p != "manifest.json"),
                "libraries": index.get("libraries") if isinstance(index.get("libraries"), list) else [],
                "components": comps,
                "assetGroups": [dict({"name": g}, **({"tile": ag[g]["tile"]} if isinstance(ag.get(g), dict) and ag[g].get("tile") else {}),
                                     **({"order": ag[g]["order"]} if isinstance(ag.get(g), dict) and isinstance(ag[g].get("order"), list) else {}))
                                for g in groups_order]}
    if isinstance(index.get("lastChange"), dict):
        manifest["lastChange"] = index["lastChange"]
    if isinstance(index.get("sections"), dict) and index["sections"]:
        manifest["sections"] = index["sections"]
    out["manifest.json"] = json.dumps(manifest, indent=2, ensure_ascii=False) + "\n"
    readme = files.get("README.md")
    if isinstance(readme, str):
        readme = readme.replace("\r\n", "\n")  # a README written on Windows: the marker's rule is "\n---\n"
        own = readme.split("\n---\n" + README_MARK)[0].rstrip() if README_MARK in readme else readme.rstrip()
        out["README.md"] = own + "\n" + readme_tail(index, m, comps, groups_order)
    out["_stale"] = [p for p in files if p.startswith("api/") and p not in out]
    return out
